import string

def is_properly_punctuated_and_capitalized(line):
    # Check if the line ends with a punctuation mark
    if line[-2] not in string.punctuation:
        return False

    # Check if the line starts with a capital letter
    if not line[0].isupper():
        return False

    # Check if all other words start with a capital letter
    words = line.split()
    for word in words[1:]:
        if not word[0].isupper():
            return False

    # Check if all punctuation marks are properly placed
    punctuation_marks = [',', ';', ':', '!', '?', '.']
    for mark in punctuation_marks:
        if mark in line:
            if not line.endswith(mark) and not line[line.index(mark) - 1].islower():
                return False

    return True

# Test the function
